import{_ as t,o,c as a,a2 as i}from"./chunks/framework.BN3Eol-0.js";const g=JSON.parse('{"title":"UXD-040 — The gallery pages: the viewer is a fitted grid, the hub strips keep their text, one .page-note footer under every gallery page","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-040-gallery-viewer-fits-hub-strips-keep-text-and-one-page-note.md","filePath":"uxs/decisions/UXD-040-gallery-viewer-fits-hub-strips-keep-text-and-one-page-note.md"}'),s={name:"uxs/decisions/UXD-040-gallery-viewer-fits-hub-strips-keep-text-and-one-page-note.md"};function r(n,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="uxd-040-—-the-gallery-pages-the-viewer-is-a-fitted-grid-the-hub-strips-keep-their-text-one-page-note-footer-under-every-gallery-page" tabindex="-1">UXD-040 — The gallery pages: the viewer is a fitted grid, the hub strips keep their text, one <code>.page-note</code> footer under every gallery page <a class="header-anchor" href="#uxd-040-—-the-gallery-pages-the-viewer-is-a-fitted-grid-the-hub-strips-keep-their-text-one-page-note-footer-under-every-gallery-page" aria-label="Permalink to &quot;UXD-040 — The gallery pages: the viewer is a fitted grid, the hub strips keep their text, one `.page-note` footer under every gallery page&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted (built; checked by a new e2e spec on three projects and screenshots, not yet by the operator)</li><li><strong>Date</strong>: 2026-11-14 (proposed and decided)</li><li><strong>Decider</strong>: the operator, 2026-11-14 — the recommendations of <code>docs/wip/2026-11-14-slice-F4-brief.md</code> §12 approved as written (&quot;I&#39;m okay with all the recommendations. Go for them.&quot;: decisions 42a, 43a, 44a)</li><li><strong>Answers</strong>: G2, G3, G4, G5, G6 of the UX feedback plan; slice F4</li><li><strong>Builds on</strong>: <a href="./UXD-009-deep-sky-viewer-fits-one-screen">UXD-009</a> (the viewer fits one screen; this is its build), <a href="./UXD-012-one-page-shell">UXD-012</a> (the shell file holds the note), <a href="./UXD-001-ui-accent-blue-replaces-teal">UXD-001</a> (no teal), <a href="./UXD-002-type-scale-and-the-11px-floor">UXD-002</a> (the caption keeps italic at 14 px)</li><li><strong>Changes</strong>: <code>src/routes/gallery/deep-sky/+page.svelte</code>, <code>src/routes/gallery/+page.svelte</code>, <code>src/routes/posters/+page.svelte</code>, <code>src/routes/patches/+page.svelte</code>, <code>src/routes/sourcing/+page.svelte</code>, <code>src/lib/styles/page-shell.css</code>, <code>tests/e2e/gallery.spec.ts</code> (new), <code>tests/e2e/posters.spec.ts</code>. No file under <code>static/images/</code>, <code>static/data/</code> or <code>messages/</code> changed; no hero, slot or override.</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><strong>G6.</strong> On <code>/gallery/deep-sky</code> the lightbox figure was a flex column with <code>max-height: 90vh</code> and an image capped at <code>72vh</code>, so the caption stack below it (observatory line, title, designation, caption, facts row, credit line, &quot;show in the sky&quot; button, about 315 px) did not fit a laptop: at 1366x768 the image spanned y 38 to 591, the facts&#39; labels sat at the bottom edge and every value (y 768 to 788), the credit line (y 860) and the button (y 886 to 920) were below the screen; at 1440x900 the credit line (y 962) and the button (y 988 to 1022) were. <strong>G4.</strong> The footer where sources are discussed existed as four footers in two designs (deep-sky and posters: a frame, 12 px Space Mono at 70% white; patches and sourcing: a top rule, 14 px at 60% white). <strong>Hub strips (found while measuring, not an operator point).</strong> On <code>/gallery</code> the posters and insignia strips clamped their text to two lines (&quot;free to…&quot;, &quot;with a sourcing wall for…&quot;) and the posters text, 596 px right edge, ran under the first thumbnail (left edge 512 px).</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>The viewer is a grid (42a; G6).</strong> <code>.lb-figure</code> is <code>display: grid</code> with two rows, the image and the caption stack, <code>max-height: calc(100svh - 80px)</code>; the image takes the height the stack leaves (<code>max-height: 100%</code>, its own aspect kept), so the facts, the credit line and the button are always inside the window. The figure is <code>overflow: auto</code>: on a phone, and in a window too short for both (a phone in landscape), it scrolls instead of shrinking the picture away. The image row has a 200 px floor (<code>minmax(200px, 1fr)</code>, not <code>minmax(0, 1fr)</code>: with 0 the picture of a landscape phone, 358 px of figure height under a 330 px stack, would be about 30 px high). The caption stack&#39;s spacing is tightened by 4 px at five places (about 16 px in all). UXD-009&#39;s label above value stays; the facts were already <code>dt</code> over <code>dd</code>. The &quot;show in the sky&quot; button&#39;s text is <code>var(--color-bg)</code> (it was <code>#06231f</code>, a dark teal, 4.02:1 on the gradient&#39;s <code>#5070ff</code> end; <code>#04040c</code> is 4.96:1 on <code>#5070ff</code> and 8.32:1 on <code>#8aa0ff</code>). One page uses this viewer; the panel galleries have their own (<code>PanelLightbox</code>, not this slice).</li><li><strong>G2 to G4 mean <code>/gallery/deep-sky</code> (43a).</strong> The page with the filter pills and the footer where sources are discussed. G2 and G3 were closed by UXD-012 and UXD-014 and are verified at HEAD, not redone; G4&#39;s colour was closed by UXD-001, its font is item 3.</li><li><strong>One <code>.page-note</code> (44a; G4).</strong> <code>src/lib/styles/page-shell.css</code> holds one class for the footer of <code>/gallery/deep-sky</code>, <code>/posters</code>, <code>/patches</code> and <code>/sourcing</code>: a 1 px frame at 8% white with 4 px corners, <code>20px 24px</code> padding, 44 px above, Space Mono <code>--size-meta</code> (12 px), line-height 1.7, 70% white, <code>strong</code> and links in <code>--color-state</code> (the muted blue), links underlined. The four local footer rules are gone (<code>git grep -n &quot;gallery-footer\\|patches-footer\\|sourcing-footer&quot; src</code> returns nothing). <code>/patches</code> and <code>/sourcing</code> change from 14 px at 60% white under a rule to the framed 12 px note; <code>/gallery</code>&#39;s <code>.aside</code> (a one-line pointer to the sourcing wall, not a footer of a collection) is not changed.</li><li><strong>The hub strips keep their text (found in F4).</strong> On <code>/gallery</code> a strip&#39;s height is a minimum (<code>min-height</code>, was <code>height</code>) and the text is in flow, so it sets the band&#39;s height and the two-line clamp is gone; the posters and insignia strips (<code>.strip-beside</code>) hold their text in 40% of the width and start their art at 40%, so no text runs under a thumbnail (the art is clipped on the right); on a phone the art sits behind the text under a heavier scrim. The deep-sky strip keeps its photo behind the text and its scrim.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>A fifth gallery-family footer uses the class and writes no footer rule.</li><li>The figure is a scroll container: the image&#39;s 60 px shadow is clipped at the figure&#39;s edge (it was invisible on the 92% dark backdrop).</li><li>A strip with a longer translation grows taller; it is never cut.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p><code>tests/e2e/gallery.spec.ts</code> (new). Against the build before the change it failed 12 of 13 viewer tests (all but label-above-value) (the first value&#39;s bottom at 788 against 768); after it, on desktop-chromium, mobile-chromium and mobile-landscape-chromium: the viewer on Pillars of Creation (en and de) and the longest caption (Cartwheel, de) at 1366x768 and 1440x900, every one of the 50 images in <code>de</code> through the arrow keys at both sizes (image at least 300 px high, every fact value, the credit line and the button inside the window), the figure scrolling and every element reachable at 390x844 and 844x390, label above value, Escape and the arrows, the button text not teal and at least 4.5:1, the four footers&#39; computed style equal, the three strips&#39; text not clipped and, from 561 px, not under a thumbnail. Measured, Pillars of Creation: at 1366x768 the image is y 40 to 415 (375 px high), the first value y 582 to 602, the credit line y 668 to 684, the button y 694 to 728 (window 768); at 1440x900 the image is 507 px high and the button ends at y 860 (window 900); at 844x390 the image is 200 px and the figure scrolls (scroll height 513, client height 310).</p><p>Not checked: Firefox and WebKit (<code>100svh</code> and <code>overflow: hidden auto</code> were tried in Chromium only), a real phone, <code>ru</code>, <code>ar</code> and the other 11 locales&#39; viewers (the de loop covers the longest captions of the set; <code>ar</code> is not run).</p>',11)])])}const u=t(s,[["render",r]]);export{g as __pageData,u as default};
